{"command": "python3 - <<'PY'
import workcell, sys, time
pairs = []
for i in range(1,7):
    pairs.append((f'C-{i:02d}', 'crate-A', i))
for i in range(7,13):
    pairs.append((f'C-{i:02d}', 'crate-B', i-6))
for item, crate, slot in pairs:
    r = workcell.call('robot','pick', item)
    print(f'pick {item}: ok={r.ok} {r.text.strip()}')
    if not r.ok:
        sys.exit(1)
    r = workcell.call('robot','place', crate, str(slot))
    print(f'place {crate} {slot}: ok={r.ok} {r.text.strip()}')
    if not r.ok:
        sys.exit(1)
print('All placements done')
r = workcell.call('cell','status')
print(r.text)
PY"}

